  "app/src/main/res/values/colors.xml": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<resources>\n    <!-- Islamic Emerald & Gold Palette -->\n    <color name=\"primary_emerald\">#0C5A38</color>\n    <color name=\"primary_emerald_dark\">#083D26</color>\n    <color name=\"primary_emerald_light\">#167D50</color>\n    <color name=\"accent_gold\">#D4AF37</color>\n    <color name=\"accent_gold_light\">#F5E6AB</color>\n    <color name=\"bg_light\">#F7FAF8</color>\n    <color name=\"surface_card\">#FFFFFF</color>\n    <color name=\"text_primary\">#1A2E26</color>\n    <color name=\"text_secondary\">#526E63</color>\n    <color name=\"text_tertiary\">#8BA398</color>\n    <color name=\"border_subtle\">#E2ECE6</color>\n    <color name=\"highlight_active\">#EBF7F0</color>\n</resources>\n",
  "app/src/main/res/values/strings.xml": "<resources>\n    <string name=\"app_name\">Pakistan Prayer Times</string>\n    <string name=\"title_home\">Home</string>\n    <string name=\"title_monthly\">Monthly Timetable</string>\n    <string name=\"title_settings\">Settings</string>\n\n    <!-- Prayer Names -->\n    <string name=\"prayer_fajr\">Fajr</string>\n    <string name=\"prayer_sunrise\">Sunrise</string>\n    <string name=\"prayer_dhuhr\">Dhuhr</string>\n    <string name=\"prayer_asr\">Asr</string>\n    <string name=\"prayer_maghrib\">Maghrib</string>\n    <string name=\"prayer_isha\">Isha</string>\n\n    <!-- Prayer Status -->\n    <string name=\"current_prayer\">Current Prayer</string>\n    <string name=\"next_prayer\">Next Prayer</string>\n    <string name=\"next_prayer_in\">Next prayer in</string>\n    <string name=\"time_remaining\">Remaining</string>\n\n    <!-- Navigation & Dates -->\n    <string name=\"prev_day\">Previous Day</string>\n    <string name=\"today\">Today</string>\n    <string name=\"next_day\">Next Day</string>\n    <string name=\"select_city\">Select City</string>\n    <string name=\"select_month\">Select Month</string>\n\n    <!-- Settings -->\n    <string name=\"settings_selected_city\">Selected City</string>\n    <string name=\"settings_calc_method\">Calculation Method</string>\n    <string name=\"settings_calc_method_val\">University of Islamic Sciences, Karachi</string>\n    <string name=\"settings_asr_method\">Asr Juristic Method</string>\n    <string name=\"settings_asr_method_val\">Hanafi (Shadow ratio: 2x)</string>\n    <string name=\"settings_time_format\">Time Format</string>\n    <string name=\"settings_12_hour\">12-Hour (AM/PM)</string>\n    <string name=\"settings_24_hour\">24-Hour</string>\n    <string name=\"settings_language\">Language</string>\n    <string name=\"settings_lang_en\">English</string>\n    <string name=\"settings_lang_ur\">اردو (Urdu)</string>\n    <string name=\"settings_about\">About Application</string>\n    <string name=\"calc_info_title\">Calculation Information</string>\n    <string name=\"calc_info_desc\">Prayer times are calculated according to the University of Islamic Sciences, Karachi calculation method using astronomical calculations and the geographic coordinates of the selected city.\\n\\nFajr angle: 18°\\nIsha angle: 18°\\nAsr: Hanafi juristic method\\nTime zone: Pakistan Standard Time (UTC+05:00)\\n\\nPlease note: Calculated astronomical prayer start times represent the earliest permissible time for prayer and may differ from your local mosque\\'s congregation (Jamaat/Iqamah) schedule.</string>\n\n    <!-- Cities -->\n    <string name=\"city_nowshera\">Nowshera</string>\n    <string name=\"city_peshawar\">Peshawar</string>\n    <string name=\"city_charsadda\">Charsadda</string>\n    <string name=\"city_mardan\">Mardan</string>\n    <string name=\"city_attock\">Attock</string>\n</resources>\n",
  "app/src/main/res/values/themes.xml": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<resources>\n    <style name=\"Theme.PakistanPrayerTimes\" parent=\"android:Theme.Material.Light.NoActionBar\">\n        <item name=\"android:statusBarColor\">#0C5A38</item>\n        <item name=\"android:navigationBarColor\">#F7FAF8</item>\n        <item name=\"android:windowLightNavigationBar\">true</item>\n    </style>\n</resources>\n",
  "app/src/main/res/values-ur/strings.xml": "<resources>\n    <string name=\"app_name\">پاکستان نماز کے اوقات</string>\n    <string name=\"title_home\">صفحہ اول</string>\n    <string name=\"title_monthly\">ماہانہ نظام الاوقات</string>\n    <string name=\"title_settings\">ترتیبات</string>\n\n    <!-- Prayer Names -->\n    <string name=\"prayer_fajr\">فجر</string>\n    <string name=\"prayer_sunrise\">طلوع آفتاب</string>\n    <string name=\"prayer_dhuhr\">ظہر</string>\n    <string name=\"prayer_asr\">عصر</string>\n    <string name=\"prayer_maghrib\">مغرب</string>\n    <string name=\"prayer_isha\">عشاء</string>\n\n    <!-- Prayer Status -->\n    <string name=\"current_prayer\">موجودہ نماز</string>\n    <string name=\"next_prayer\">اگلی نماز</string>\n    <string name=\"next_prayer_in\">اگلی نماز میں باقی وقت</string>\n    <string name=\"time_remaining\">باقی وقت</string>\n\n    <!-- Navigation & Dates -->\n    <string name=\"prev_day\">پچھلا دن</string>\n    <string name=\"today\">آج</string>\n    <string name=\"next_day\">اگلا دن</string>\n    <string name=\"select_city\">شہر منتخب کریں</string>\n    <string name=\"select_month\">مہینہ منتخب کریں</string>\n\n    <!-- Settings -->\n    <string name=\"settings_selected_city\">منتخب شہر</string>\n    <string name=\"settings_calc_method\">طریقہ حساب</string>\n    <string name=\"settings_calc_method_val\">جامعہ علوم اسلامیہ علامہ بنوری ٹاؤن، کراچی</string>\n    <string name=\"settings_asr_method\">طریقہ عصر</string>\n    <string name=\"settings_asr_method_val\">حنفی (سایہ مثلین)</string>\n    <string name=\"settings_time_format\">وقت کا فارمیٹ</string>\n    <string name=\"settings_12_hour\">12 گھنٹے (صبح / شام)</string>\n    <string name=\"settings_24_hour\">24 گھنٹے</string>\n    <string name=\"settings_language\">زبان</string>\n    <string name=\"settings_lang_en\">English</string>\n    <string name=\"settings_lang_ur\">اردو</string>\n    <string name=\"settings_about\">ایپلیکیشن کے متعلق</string>\n    <string name=\"calc_info_title\">اوقات نماز کے حساب کی معلومات</string>\n    <string name=\"calc_info_desc\">نماز کے اوقات جامعہ علوم اسلامیہ علامہ بنوری ٹاؤن کراچی کے مروجہ فلکیاتی قواعد اور منتخب شہر کے جغرافیائی نقاط (طول بلد و عرض بلد) کی بنیاد پر حساب کیے جاتے ہیں۔\\n\\nفجر زاویہ: 18 ڈگری زیر افق\\nعشاء زاویہ: 18 ڈگری زیر افق\\nعصر: حنفی طریقہ (دوگنا سایہ)\\nٹائم زون: پاکستان کا معیاری وقت (UTC+05:00)\\n\\nنوٹ: یہ اوقات نماز کے دخول کے اصل شرعی فلکیاتی اوقات ہیں۔ مساجد کے باجماعت اقامت کے اوقات مقامی انتظامیہ کے مطابق مختلف ہو سکتے ہیں۔</string>\n\n    <!-- Cities -->\n    <string name=\"city_nowshera\">نوشہرہ</string>\n    <string name=\"city_peshawar\">پشاور</string>\n    <string name=\"city_charsadda\">چارسدہ</string>\n    <string name=\"city_mardan\">مردان</string>\n    <string name=\"city_attock\">اٹک</string>\n</resources>\n",
  "app/src/main/res/xml/backup_rules.xml": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<full-backup-content>\n    <include domain=\"sharedpref\" path=\".\"/>\n</full-backup-content>\n",
